mapper.select:
select id, activity_id, target_id, accepted_at, response_state, current_revision_no
from edu_activity_response
where target_id = #{targetId}

select r.id, r.activity_id, r.target_id, r.accepted_at, r.response_state, r.current_revision_no
from edu_activity_response r
inner join edu_activity_target t on t.id = r.target_id
where r.activity_id = #{activityId}
  and t.student_user_id = #{studentUserId}

mapper.insert:
insert into edu_activity_response (
    activity_id, target_id, accepted_at, response_state, current_revision_no
) values (
    #{activityId}, #{targetId}, #{acceptedAt}, #{responseState}, #{currentRevisionNo}
)
